def leaves(x,p):
 if isinstance(x,dict):
  for k,v in x.items():yield from leaves(v,p+'.'+k)
 elif isinstance(x,list):
  for i,v in enumerate(x):yield from leaves(v,p+'.'+str(i))
 elif x is not None:yield p
